import{_ as n,o as s,c as e,a2 as t}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"综合分析","description":"","frontmatter":{},"headers":[],"relativePath":"shenlun/zonghe-fenxi.md","filePath":"shenlun/zonghe-fenxi.md"}'),l={name:"shenlun/zonghe-fenxi.md"};function p(r,a,i,d,o,h){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="综合分析" tabindex="-1">综合分析 <a class="header-anchor" href="#综合分析" aria-label="Permalink to &quot;综合分析&quot;">​</a></h1><p>综合分析题在概括的基础上，要求你理解材料的深层含义，分析现象背后的原因、影响和本质。</p><h2 id="常见题型" tabindex="-1">常见题型 <a class="header-anchor" href="#常见题型" aria-label="Permalink to &quot;常见题型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题型</th><th>问法</th><th>特点</th></tr></thead><tbody><tr><td>词句理解</td><td>&quot;谈谈你对...的理解&quot;</td><td>解释含义 + 分析原因/影响 + 得出结论</td></tr><tr><td>观点分析</td><td>&quot;对...观点，你怎么看&quot;</td><td>表态 + 分析 + 建议</td></tr><tr><td>现象分析</td><td>&quot;分析...现象&quot;</td><td>是什么 → 为什么 → 怎么办</td></tr></tbody></table><hr><h2 id="一、词句理解题" tabindex="-1">一、词句理解题 <a class="header-anchor" href="#一、词句理解题" aria-label="Permalink to &quot;一、词句理解题&quot;">​</a></h2><h3 id="答题框架" tabindex="-1">答题框架 <a class="header-anchor" href="#答题框架" aria-label="Permalink to &quot;答题框架&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 解释含义（是什么）</span></span>
<span class="line"><span>   - 字面意思 + 深层含义</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 展开分析（为什么）</span></span>
<span class="line"><span>   - 原因、影响、表现</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 得出结论（怎么办）</span></span>
<span class="line"><span>   - 简要提出对策或总结提升</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><blockquote><p>谈谈你对&quot;人在做，天在看&quot;的理解。</p></blockquote><p><strong>答题结构</strong>：</p><ol><li>释义：这句话强调做人做事要对得起良心、遵守道德法律</li><li>分析：当前一些领域存在诚信缺失问题；需要加强社会信用体系建设</li><li>总结：每个人都应自律，同时制度要跟上</li></ol><hr><h2 id="二、观点分析题" tabindex="-1">二、观点分析题 <a class="header-anchor" href="#二、观点分析题" aria-label="Permalink to &quot;二、观点分析题&quot;">​</a></h2><h3 id="答题框架-1" tabindex="-1">答题框架 <a class="header-anchor" href="#答题框架-1" aria-label="Permalink to &quot;答题框架&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 表态：正确/错误/片面/辩证看待</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 分析：</span></span>
<span class="line"><span>   - 正确的部分 → 为什么对</span></span>
<span class="line"><span>   - 错误的部分 → 为什么错</span></span>
<span class="line"><span>   - 如果片面 → 补充完整视角</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 建议：怎么做更好</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><hr><h2 id="三、现象分析题" tabindex="-1">三、现象分析题 <a class="header-anchor" href="#三、现象分析题" aria-label="Permalink to &quot;三、现象分析题&quot;">​</a></h2><h3 id="答题框架-是什么-→-为什么-→-怎么办" tabindex="-1">答题框架 = &quot;是什么 → 为什么 → 怎么办&quot; <a class="header-anchor" href="#答题框架-是什么-→-为什么-→-怎么办" aria-label="Permalink to &quot;答题框架 = &quot;是什么 → 为什么 → 怎么办&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 是什么 → 概括现象，下定义</span></span>
<span class="line"><span>2. 为什么 → 分析原因（多角度）</span></span>
<span class="line"><span>   - 主观原因 + 客观原因</span></span>
<span class="line"><span>   - 内因 + 外因</span></span>
<span class="line"><span>   - 直接原因 + 深层原因</span></span>
<span class="line"><span>3. 怎么办 → 提出对策（简要）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="⚠️-常见错误" tabindex="-1">⚠️ 常见错误 <a class="header-anchor" href="#⚠️-常见错误" aria-label="Permalink to &quot;⚠️ 常见错误&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误</th><th>正确做法</th></tr></thead><tbody><tr><td>只谈看法不结合材料</td><td>每个观点都要有材料依据</td></tr><tr><td>分析空泛无深度</td><td>从多角度、多层次展开</td></tr><tr><td>只分析不总结</td><td>分析完要有结论或对策</td></tr><tr><td>表态模糊</td><td>明确指出对还是错，不要&quot;好像有道理&quot;</td></tr></tbody></table><hr><h2 id="📝-练习记录" tabindex="-1">📝 练习记录 <a class="header-anchor" href="#📝-练习记录" aria-label="Permalink to &quot;📝 练习记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日期</th><th>题目（词句/观点/现象）</th><th>得分</th><th>不足</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr></tbody></table>`,26)])])}const u=n(l,[["render",p]]);export{b as __pageData,u as default};
